def solve(inputs):
    M = inputs['M']
    power = inputs['power']
    mod = inputs['mod']
    n = len(M)

    result = [[0] * n for _ in range(n)]
    current = M[:]

    for _ in range(power):
        next_matrix = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    next_matrix[i][j] = (next_matrix[i][j] + current[i][k] * M[k][j]) % mod
        current = next_matrix

    return sum(sum(row) for row in result)

